CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(128) PRIMARY KEY, applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS users (
 id CHAR(36) PRIMARY KEY, phone VARCHAR(32) NULL, email VARCHAR(320) NULL, name VARCHAR(160) NOT NULL DEFAULT '', state VARCHAR(120) NOT NULL DEFAULT '', district VARCHAR(120) NOT NULL DEFAULT '', language VARCHAR(32) NOT NULL DEFAULT 'English', avatar_path VARCHAR(500) NULL, avatar_updated_at DATETIME(3) NULL, is_deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at DATETIME(3) NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY users_phone_unique (phone), UNIQUE KEY users_email_unique (email)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS user_sessions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME(3) NOT NULL, revoked_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), last_seen_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX sessions_user_active (user_id, expires_at, revoked_at), CONSTRAINT sessions_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_sessions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, title VARCHAR(500) NOT NULL DEFAULT 'New conversation', preview TEXT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), last_message_at DATETIME(3) NULL, INDEX chat_sessions_user_updated (user_id, updated_at, id), CONSTRAINT chat_sessions_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_messages (id CHAR(36) PRIMARY KEY, session_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, client_message_id VARCHAR(128) NULL, role ENUM('user','assistant') NOT NULL, content MEDIUMTEXT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), message_type ENUM('text','image','document','audio') NOT NULL DEFAULT 'text', file_path VARCHAR(500) NULL, file_name VARCHAR(500) NULL, mime_type VARCHAR(255) NULL, metadata JSON NULL, UNIQUE KEY chat_messages_idempotency (user_id, client_message_id), INDEX chat_messages_session_created (session_id, created_at, id), CONSTRAINT chat_messages_session_fk FOREIGN KEY (session_id) REFERENCES chat_sessions(id) ON DELETE CASCADE, CONSTRAINT chat_messages_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_message_translations (message_id CHAR(36) NOT NULL, lang ENUM('en','hi','te') NOT NULL, content MEDIUMTEXT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (message_id, lang), CONSTRAINT msg_translation_fk FOREIGN KEY (message_id) REFERENCES chat_messages(id) ON DELETE CASCADE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_session_translations (session_id CHAR(36) NOT NULL, lang ENUM('en','hi','te') NOT NULL, title VARCHAR(500) NULL, preview TEXT NULL, updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (session_id, lang), CONSTRAINT session_translation_fk FOREIGN KEY (session_id) REFERENCES chat_sessions(id) ON DELETE CASCADE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS translation_cache (text_hash CHAR(64) NOT NULL, lang ENUM('en','hi','te') NOT NULL, content MEDIUMTEXT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (text_hash, lang)) CHARACTER SET utf8mb4;
CREATE TABLE IF NOT EXISTS files (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, storage_key VARCHAR(500) NOT NULL UNIQUE, original_name VARCHAR(500) NOT NULL, mime_type VARCHAR(255) NOT NULL, byte_size BIGINT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), deleted_at DATETIME(3) NULL, INDEX files_user_created (user_id, created_at), CONSTRAINT files_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS auth_challenges (id CHAR(36) PRIMARY KEY, identity_value VARCHAR(320) NOT NULL, identity_type ENUM('phone','email') NOT NULL, provider_request_id VARCHAR(255) NULL, binding_hash CHAR(64) NOT NULL, expires_at DATETIME(3) NOT NULL, consumed_at DATETIME(3) NULL, attempts TINYINT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX challenge_lookup (identity_value, expires_at));
